use chewing_policy_core::{f_hold::{FHoldGesture,Event,Effect},shift_letter::{FCompositionBuffer,ShiftLetterSession,ShiftMode,ASCIIComposition},technical_lexicon::TechnicalLexicon};
use std::time::Duration;
#[test]fn unused_hold_restores_once_at_and_beyond_deadline(){for ms in [149,150,151,1000]{let mut g=FHoldGesture::default();g.handle(Event::Press{eligible:true,repeating:false});g.handle(Event::Elapsed(Duration::from_millis(ms)));assert!(g.handle(Event::Release).contains(&Effect::ReplayTap));assert!(g.handle(Event::Release).is_empty());}}
#[test]fn executed_command_suppresses_restore(){let mut g=FHoldGesture::default();g.handle(Event::Press{eligible:true,repeating:false});g.handle(Event::Elapsed(Duration::from_millis(151)));g.handle(Event::LayerCommand);assert!(!g.handle(Event::Release).contains(&Effect::ReplayTap));}
#[test]fn cancellation_never_restores(){for used in [false,true]{let mut g=FHoldGesture::default();g.handle(Event::Press{eligible:true,repeating:false});g.handle(Event::Elapsed(Duration::from_millis(151)));if used{g.handle(Event::LayerCommand);}assert!(!g.handle(Event::Cancel).contains(&Effect::ReplayTap));assert!(g.handle(Event::Release).is_empty());assert!(g.handle(Event::Timeout).is_empty());}}
#[test]fn used_history_survives_deletion_to_empty(){let lex=TechnicalLexicon::default();let mut b=FCompositionBuffer::new(None,&lex);assert!(!b.layer_used());b.append("+");b.backspace();assert!(b.symbols().is_empty());assert!(b.layer_used());b.backspace();assert!(b.layer_used());}
#[test]fn rejected_or_empty_command_does_not_count(){let lex=TechnicalLexicon::default();let mut b=FCompositionBuffer::new(None,&lex);b.append("");b.append("\n");b.append(&"x".repeat(257));b.backspace();assert!(!b.layer_used());assert!(b.symbols().is_empty());}
#[test]fn idle_buffer_preserves_original_cursor_and_text(){let lex=TechnicalLexicon::default();let base=ShiftLetterSession::new(ASCIIComposition::new("abcd",Some(2),0,&lex),ShiftMode::Word);let mut b=FCompositionBuffer::new(Some(base),&lex);b.backspace();assert!(!b.layer_used());assert_eq!(b.preview(&lex).raw,"abcd");assert_eq!(b.preview(&lex).cursor,2);}
